#include <algorithm>
#include <array>
#include <cmath>
#include <cstddef>
#include <cstdint>
#include <string>
#include <vector>

struct FoundString { std::size_t offset; std::string text; bool wide; };

static bool printable(std::uint8_t b) { return b >= 0x20 && b <= 0x7E; }

std::vector<FoundString> findStrings(const std::vector<std::uint8_t>& bytes, std::size_t minLength)
{
    std::vector<FoundString> found;
    const std::size_t n{ bytes.size() };
    for (std::size_t i{ 0 }; i < n;)
    {
        if (!printable(bytes[i])) { ++i; continue; }
        const std::size_t start{ i };
        while (i < n && printable(bytes[i])) ++i;
        if (i - start >= minLength) found.push_back({ start, std::string(bytes.begin() + start, bytes.begin() + i), false });
    }
    for (std::size_t i{ 0 }; i + 1 < n;)
    {
        if (!printable(bytes[i]) || bytes[i + 1] != 0) { ++i; continue; }
        const std::size_t start{ i };
        std::string text;
        while (i + 1 < n && printable(bytes[i]) && bytes[i + 1] == 0) { text += static_cast<char>(bytes[i]); i += 2; }
        if (text.size() >= minLength) found.push_back({ start, text, true });
        else i = start + 1;
    }
    std::stable_sort(found.begin(), found.end(), [](const FoundString& a, const FoundString& b) {
        return a.offset != b.offset ? a.offset < b.offset : (!a.wide && b.wide);
    });
    return found;
}

double entropy(const std::vector<std::uint8_t>& bytes, std::size_t begin, std::size_t size)
{
    if (size == 0) return 0.0;
    std::array<std::size_t, 256> counts{};
    for (std::size_t i{ begin }; i < begin + size; ++i) ++counts[bytes[i]];
    double h{ 0.0 };
    for (std::size_t c : counts)
    {
        if (c == 0) continue;
        const double p{ static_cast<double>(c) / static_cast<double>(size) };
        h -= p * std::log2(p);
    }
    return h;
}

