using Bytes = std::vector<std::uint8_t>;
static Bytes sample()
{
    Bytes b{ 0x01, 'H', 'e', 'l', 'l', 'o', 0, 0x02, 'W', 0, 'i', 0, 'd', 0, 'e', 0, 0, 0, 'a', 'b', 0, 0xFF };
    for (char c : std::string("Longer!")) b.push_back(static_cast<std::uint8_t>(c));
    return b;
}

TEST("ascii and wide strings") {
    const auto s{ findStrings(sample(), 4) };
    CHECK_EQ(s.size(), 3u);
    if (s.size() != 3) return;
    CHECK_EQ(s[0].offset, 1u); CHECK_EQ(s[0].text, std::string("Hello")); CHECK(!s[0].wide);
    CHECK_EQ(s[1].offset, 8u); CHECK_EQ(s[1].text, std::string("Wide")); CHECK(s[1].wide);
    CHECK_EQ(s[2].offset, 22u); CHECK_EQ(s[2].text, std::string("Longer!"));
}
TEST("minimum length") {
    CHECK_EQ(findStrings(sample(), 2).size(), 4u);
    CHECK_EQ(findStrings(sample(), 6).size(), 1u);
    CHECK(findStrings(Bytes{}, 4).empty());
}
TEST("wide strings at odd offsets") {
    const Bytes b{ 0xFF, 'C', 0, 'a', 0, 'r', 0, 't', 0, 0, 0 };
    const auto s{ findStrings(b, 4) };
    CHECK_EQ(s.size(), 1u);
    if (!s.empty()) { CHECK_EQ(s[0].offset, 1u); CHECK_EQ(s[0].text, std::string("Cart")); CHECK(s[0].wide); }
}
TEST("entropy") {
    CHECK_NEAR(entropy(Bytes(64, 0x41), 0, 64), 0.0, 1e-9);
    Bytes all(256);
    for (int i{ 0 }; i < 256; ++i) all[i] = static_cast<std::uint8_t>(i);
    CHECK_NEAR(entropy(all, 0, 256), 8.0, 1e-9);
    const Bytes halves{ 0, 0, 1, 1 };
    CHECK_NEAR(entropy(halves, 0, 4), 1.0, 1e-9);
    CHECK_NEAR(entropy(all, 0, 4), 2.0, 1e-9);
    CHECK_NEAR(entropy(all, 10, 0), 0.0, 1e-9);
}

